// The flavor/cuisine-profile tags recipes get auto-tagged with (see the tags
// array on each Recipe) — reused both as the taste-swipe's implicit signal
// and as the explicit "Firm Dislikes" onboarding step's selectable options.
export const FLAVOR_PROFILES = [
  { id: 'Curry', label: 'Curries' },
  { id: 'Spicy', label: 'Spicy Food' },
  { id: 'Tomato-based', label: 'Tomato-based Sauces' },
  { id: 'Creamy', label: 'Creamy Sauces' },
  { id: 'Cheesy', label: 'Very Cheesy Dishes' },
  { id: 'Asian-inspired', label: 'Asian-inspired' },
  { id: 'Mexican-inspired', label: 'Mexican-inspired' },
  { id: 'Italian-inspired', label: 'Italian-inspired' },
  { id: 'Mediterranean', label: 'Mediterranean' },
];

// Allergens that already map cleanly onto an existing DIETARY_RESTRICTIONS id
// (and therefore a DietaryFlags key) — no extra logic needed for these.
const ALLERGY_TO_RESTRICTION: Record<string, string> = {
  peanuts: 'nut-allergy',
  'tree-nuts': 'nut-allergy',
  dairy: 'dairy-free',
  wheat: 'gluten-free',
  gluten: 'gluten-free',
};

// Allergens with no dedicated DietaryFlags field — matched by keyword against
// ingredient names instead. Best-effort, same caveat as halal/kosher: good
// enough to filter a recipe list, not a substitute for checking labels.
const ALLERGY_KEYWORDS: Record<string, string[]> = {
  eggs: ['egg'],
  soy: ['soy', 'tofu', 'tempeh', 'edamame', 'miso'],
  fish: ['salmon', 'cod', 'tuna', 'mackerel', 'haddock', 'anchovy', 'anchovies', 'sardine', 'fish'],
  shellfish: ['prawn', 'shrimp', 'crab', 'mussel', 'scallop', 'squid'],
};

export function allergyRestrictionIds(allergyIds: string[]): string[] {
  const mapped = allergyIds.map((id) => ALLERGY_TO_RESTRICTION[id]).filter((id): id is string => Boolean(id));
  return [...new Set(mapped)];
}

function recipeContainsAllergen(recipe: Recipe, allergyId: string): boolean {
  const keywords = ALLERGY_KEYWORDS[allergyId];
  if (!keywords) return false; // handled via allergyRestrictionIds instead
  return recipe.ingredients.some((ing) => keywords.some((kw) => ing.name.toLowerCase().includes(kw)));
}

export function matchesAllergies(recipe: Recipe, allergyIds: string[]): boolean {
  return !allergyIds.some((id) => recipeContainsAllergen(recipe, id));
}

// Combines dietary restrictions with allergy-derived exclusions — the one
// filter every screen that surfaces recipes should call.
export function filterByRestrictionsAndAllergies(
  recipes: Recipe[],
  restrictionIds: string[] = [],
  allergyIds: string[] = []
): Recipe[] {
  const combinedRestrictions = [...restrictionIds, ...allergyRestrictionIds(allergyIds)];
  return filterByRestrictions(recipes, combinedRestrictions).filter((r) => matchesAllergies(r, allergyIds));
}

// A full-size oven can always do what an air fryer does (it's strictly more
// capable — more space, more heat control), so anything tagged 'air-fryer'
// is fine for an oven-only student. The reverse isn't true: an air fryer's
// basket is small, so only dishes that are dry, crisp, individual pieces
// (chips, wings, skewers, breaded bites) genuinely transfer — a traybake or
// a sauce-based bake doesn't fit or cook the same way. Those specific oven
// recipes are marked recipe.airFryerAdaptable individually rather than
// assumed for the whole 'oven' category.
function ownsOrHasSubstitute(needed: string, owned: Set<string>, recipe: Recipe): boolean {
  if (owned.has(needed)) return true;
  if (needed === 'air-fryer') return owned.has('oven');
  if (needed === 'oven') return owned.has('air-fryer') && !!recipe.airFryerAdaptable;
  return false;
}

// Only shows recipes the student can actually cook with what they told us
// they own. No selection at all (onboarding skipped/not yet reached) means
// no filtering, rather than showing nothing. If a specific combo (e.g.
// "air fryer only") has zero real matches yet, this falls back to the full
// pool rather than returning an empty list — better to suggest something
// slightly off-equipment than nothing at all.
export function filterByEquipment(recipes: Recipe[], equipmentIds: string[] = []): Recipe[] {
  if (equipmentIds.length === 0) return recipes;
  const owned = new Set(equipmentIds);
  const matches = recipes.filter((r) => r.equipment.every((needed) => ownsOrHasSubstitute(needed, owned, r)));
  return matches.length > 0 ? matches : recipes;
}

// A firm dislike (picked upfront in onboarding, matching a FLAVOR_PROFILES
// id) is a genuine "don't suggest this" — it excludes matching recipes
// outright, unlike a swiped-dislike dish, which only deprioritises via
// scoreRecipeForProfile. Same safe-fallback pattern as everywhere else: if
// this would exclude the entire pool, show the unfiltered pool instead.
export function filterByFirmDislikes(recipes: Recipe[], firmDislikeIds: string[] = []): Recipe[] {
  if (firmDislikeIds.length === 0) return recipes;
  const disliked = new Set(firmDislikeIds);
  const matches = recipes.filter((r) => !r.tags.some((t) => disliked.has(t)));
  return matches.length > 0 ? matches : recipes;
}

